CREATE TYPE "CustomerRequestPriority" AS ENUM ('LOW','NORMAL','HIGH','URGENT');
CREATE TYPE "CustomerRequestTriageStatus" AS ENUM ('UNTRIAGED','TRIAGED');
CREATE TYPE "CustomerRequestRoutingDestination" AS ENUM ('MANUAL','TASK','TECHNICAL_DOCUMENT','OPPORTUNITY');
CREATE TYPE "CustomerRequestCrmTargetType" AS ENUM ('TASK','TECHNICAL_DOCUMENT','OPPORTUNITY');
ALTER TABLE "customer_request_types" ADD COLUMN "defaultRoutingDestination" "CustomerRequestRoutingDestination" NOT NULL DEFAULT 'MANUAL';
ALTER TABLE "customer_requests" ADD COLUMN "priority" "CustomerRequestPriority" NOT NULL DEFAULT 'NORMAL', ADD COLUMN "triageStatus" "CustomerRequestTriageStatus" NOT NULL DEFAULT 'UNTRIAGED', ADD COLUMN "assignedToId" TEXT, ADD COLUMN "responsibleTeamId" TEXT, ADD COLUMN "triagedAt" TIMESTAMP(3), ADD COLUMN "triagedById" TEXT, ADD COLUMN "routingDestination" "CustomerRequestRoutingDestination", ADD COLUMN "triageReason" TEXT, ADD COLUMN "revision" INTEGER NOT NULL DEFAULT 1;
CREATE TABLE "customer_request_operational_history" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"companyId" TEXT NOT NULL,"requestId" TEXT NOT NULL,"action" TEXT NOT NULL,"actorId" TEXT NOT NULL,"previousPriority" "CustomerRequestPriority","newPriority" "CustomerRequestPriority","previousAssigneeId" TEXT,"newAssigneeId" TEXT,"previousTeamId" TEXT,"newTeamId" TEXT,"previousRoutingDestination" "CustomerRequestRoutingDestination","newRoutingDestination" "CustomerRequestRoutingDestination","internalReason" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "customer_request_operational_history_pkey" PRIMARY KEY ("id"));
CREATE TABLE "customer_request_crm_links" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"companyId" TEXT NOT NULL,"requestId" TEXT NOT NULL,"targetType" "CustomerRequestCrmTargetType" NOT NULL,"taskId" TEXT,"technicalDocumentId" TEXT,"opportunityId" TEXT,"purpose" TEXT,"idempotencyKey" TEXT,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"unlinkedAt" TIMESTAMP(3),"unlinkedById" TEXT,"unlinkReason" TEXT,CONSTRAINT "customer_request_crm_links_pkey" PRIMARY KEY ("id"),CONSTRAINT "customer_request_crm_links_exact_target_check" CHECK (("targetType"='TASK' AND "taskId" IS NOT NULL AND "technicalDocumentId" IS NULL AND "opportunityId" IS NULL) OR ("targetType"='TECHNICAL_DOCUMENT' AND "taskId" IS NULL AND "technicalDocumentId" IS NOT NULL AND "opportunityId" IS NULL) OR ("targetType"='OPPORTUNITY' AND "taskId" IS NULL AND "technicalDocumentId" IS NULL AND "opportunityId" IS NOT NULL)));
CREATE TABLE "customer_request_crm_creation_attempts" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"companyId" TEXT NOT NULL,"requestId" TEXT NOT NULL,"targetType" "CustomerRequestCrmTargetType" NOT NULL,"idempotencyKey" TEXT NOT NULL,"targetId" TEXT,"status" TEXT NOT NULL DEFAULT 'PENDING',"errorCode" TEXT,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "customer_request_crm_creation_attempts_pkey" PRIMARY KEY ("id"));
CREATE INDEX "customer_requests_org_triage_priority_submitted_idx" ON "customer_requests"("organizationId","triageStatus","priority","submittedAt");
CREATE INDEX "customer_requests_org_assignee_status_idx" ON "customer_requests"("organizationId","assignedToId","status");
CREATE INDEX "customer_requests_org_team_status_idx" ON "customer_requests"("organizationId","responsibleTeamId","status");
CREATE INDEX "customer_request_operational_history_request_created_idx" ON "customer_request_operational_history"("requestId","createdAt");
CREATE INDEX "customer_request_operational_history_org_company_created_idx" ON "customer_request_operational_history"("organizationId","companyId","createdAt");
CREATE UNIQUE INDEX "customer_request_crm_links_request_task_key" ON "customer_request_crm_links"("requestId","taskId");
CREATE UNIQUE INDEX "customer_request_crm_links_request_document_key" ON "customer_request_crm_links"("requestId","technicalDocumentId");
CREATE UNIQUE INDEX "customer_request_crm_links_request_opportunity_key" ON "customer_request_crm_links"("requestId","opportunityId");
CREATE UNIQUE INDEX "customer_request_crm_links_request_idempotency_key" ON "customer_request_crm_links"("requestId","idempotencyKey");
CREATE INDEX "customer_request_crm_links_org_company_request_unlinked_idx" ON "customer_request_crm_links"("organizationId","companyId","requestId","unlinkedAt");
CREATE UNIQUE INDEX "customer_request_crm_creation_attempts_request_key" ON "customer_request_crm_creation_attempts"("requestId","idempotencyKey");
CREATE INDEX "customer_request_crm_creation_attempts_org_request_status_idx" ON "customer_request_crm_creation_attempts"("organizationId","requestId","status");
ALTER TABLE "customer_requests" ADD CONSTRAINT "customer_requests_assignedToId_fkey" FOREIGN KEY ("assignedToId") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "customer_requests" ADD CONSTRAINT "customer_requests_responsibleTeamId_fkey" FOREIGN KEY ("responsibleTeamId") REFERENCES "teams"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "customer_requests" ADD CONSTRAINT "customer_requests_triagedById_fkey" FOREIGN KEY ("triagedById") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "customer_request_operational_history" ADD CONSTRAINT "customer_request_operational_history_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "customer_request_operational_history" ADD CONSTRAINT "customer_request_operational_history_request_fkey" FOREIGN KEY ("requestId","organizationId","companyId") REFERENCES "customer_requests"("id","organizationId","companyId") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "customer_request_operational_history" ADD CONSTRAINT "customer_request_operational_history_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "customer_request_crm_links" ADD CONSTRAINT "customer_request_crm_links_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "customer_request_crm_links" ADD CONSTRAINT "customer_request_crm_links_company_fkey" FOREIGN KEY ("companyId","organizationId") REFERENCES "companies"("id","organizationId") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "customer_request_crm_links" ADD CONSTRAINT "customer_request_crm_links_request_fkey" FOREIGN KEY ("requestId","organizationId","companyId") REFERENCES "customer_requests"("id","organizationId","companyId") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "customer_request_crm_links" ADD CONSTRAINT "customer_request_crm_links_task_fkey" FOREIGN KEY ("taskId","organizationId") REFERENCES "tasks"("id","organizationId") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "customer_request_crm_links" ADD CONSTRAINT "customer_request_crm_links_document_fkey" FOREIGN KEY ("technicalDocumentId") REFERENCES "technical_documents"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "customer_request_crm_links" ADD CONSTRAINT "customer_request_crm_links_opportunity_fkey" FOREIGN KEY ("opportunityId") REFERENCES "opportunities"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "customer_request_crm_links" ADD CONSTRAINT "customer_request_crm_links_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "customer_request_crm_links" ADD CONSTRAINT "customer_request_crm_links_unlinkedById_fkey" FOREIGN KEY ("unlinkedById") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "customer_request_crm_creation_attempts" ADD CONSTRAINT "customer_request_crm_creation_attempts_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "customer_request_crm_creation_attempts" ADD CONSTRAINT "customer_request_crm_creation_attempts_request_fkey" FOREIGN KEY ("requestId","organizationId","companyId") REFERENCES "customer_requests"("id","organizationId","companyId") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "customer_request_crm_creation_attempts" ADD CONSTRAINT "customer_request_crm_creation_attempts_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
INSERT INTO "permissions" ("id","action","name","description","group","isSystem","isActive","createdAt","updatedAt") VALUES (gen_random_uuid()::text,'customer-request:triage','تریاژ درخواست مشتری','اولویت‌بندی درخواست مشتری','خدمات مشتریان',true,true,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),(gen_random_uuid()::text,'customer-request:assign','ارجاع درخواست مشتری','تخصیص درخواست به کاربر یا تیم','خدمات مشتریان',true,true,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),(gen_random_uuid()::text,'customer-request:route','مسیریابی درخواست مشتری','انتخاب مقصد عملیاتی','خدمات مشتریان',true,true,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),(gen_random_uuid()::text,'customer-request:link','پیوند درخواست مشتری','مدیریت پیوندهای CRM','خدمات مشتریان',true,true,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT ("action") DO NOTHING;
INSERT INTO "role_permissions" ("id","role","permissionId","createdAt","updatedAt") SELECT gen_random_uuid()::text,'ADMIN'::"UserRole",p."id",CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM "permissions" p WHERE p."action" IN ('customer-request:triage','customer-request:assign','customer-request:route','customer-request:link') ON CONFLICT ("role","permissionId") DO NOTHING;
